27	```css
28	/* ==========================================================================
29	   BusinessServices — Design System
30	   Warm premium service brand: teal-ink structure, brass action color.
31	   Layers: tokens · reset · layout · header/footer · buttons · hero ·
32	           cards · portfolio/prices/about · contacts · a11y · responsive
33	   ========================================================================== */
34	
35	/* ==========================================================================
36	   1. TOKENS
37	   ========================================================================== */
38	:root {
39	    /* --- Color: structure --- */
40	    --ink:              #0F2A2E;
41	    --ink-2:            #0A1F22;
42	    --canvas:           #F7F5F1;
43	    --canvas-2:         #EFEBE4;
44	    --surface:          #FFFFFF;
45	    --border:           #E6E0D6;
46	    --border-strong:    #D6CDBE;
47	
48	    /* --- Color: text --- */
49	    --text:             #1A2E2C;
50	    --text-2:           #5C6B68;
51	    --text-3:           #8A938F;
52	    --text-on-ink:      #EDE7DD;
53	    --text-on-ink-2:    #A9B5B2;
54	
55	    /* --- Color: action --- */
56	    --accent:           #B26A20;
57	    --accent-hover:     #8F5318;
58	    --accent-soft:      #FBF1E3;
59	    --accent-line:      #E8CFA8;
60	    --accent-on-ink:    #E0A458;
61	
62	    /* --- Color: semantic --- */
63	    --price:            #2F6B4F;
64	    --badge-repair-bg:      #F6E9D5;
65	    --badge-repair-fg:      #8A5A16;
66	    --badge-cleaning-bg:    #DDE9E7;
67	    --badge-cleaning-fg:    #1F5551;
68	    --badge-montage-bg:     #DFE9DD;
69	    --badge-montage-fg:     #2F5A32;
70	
71	    /* --- Type --- */
72	    --font-display: 'Playfair Display', Georgia, 'Times New Roman', serif;
73	    --font-sans: 'Manrope', -apple-system, BlinkMacSystemFont, 'Segoe UI',
74	                 Roboto, Helvetica, Arial, sans-serif;
75	
76	    --fs-display:   clamp(2.25rem, 1.6rem + 2.6vw, 3.4rem);
77	    --fs-title:     clamp(1.9rem, 1.5rem + 1.6vw, 2.6rem);
78	    --fs-section:   clamp(1.5rem, 1.3rem + 0.9vw, 1.95rem);
79	    --fs-card:      1.2rem;
80	    --fs-body:      1rem;
81	    --fs-sm:        0.875rem;
82	    --fs-micro:     0.72rem;
83	
84	    /* --- Space (4px base) --- */
85	    --s1: 4px;  --s2: 8px;  --s3: 12px; --s4: 16px; --s5: 24px;
86	    --s6: 32px; --s7: 48px; --s8: 64px; --s9: 96px;
87	
88	    /* --- Radii --- */
89	    --r-sm: 8px; --r-md: 12px; --r-lg: 18px; --r-pill: 999px;
90	
91	    /* --- Elevation (warm-tinted, never pure black) --- */
92	    --sh-1: 0 1px 2px rgba(23, 36, 34, .05);
93	    --sh-2: 0 2px 4px rgba(23, 36, 34, .04),
94	            0 10px 20px -8px rgba(23, 36, 34, .10);
95	    --sh-3: 0 4px 8px rgba(23, 36, 34, .05),
96	            0 20px 40px -16px rgba(23, 36, 34, .20);
97	
98	    /* --- Layout --- */
99	    --header-h: 68px;
100	    --wrap: 1200px;
101	
102	    /* --- Motion --- */
103	    --t-fast: 140ms cubic-bezier(.2, .6, .3, 1);
104	    --t-base: 240ms cubic-bezier(.2, .6, .3, 1);
105	}
106	
107	/* ==========================================================================
108	   2. RESET & BASE
109	   ========================================================================== */
110	*, *::before, *::after { box-sizing: border-box; }
111	* { margin: 0; padding: 0; }
112	
113	html {
114	    -webkit-text-size-adjust: 100%;
115	    scroll-behavior: smooth;
116	}
117	
118	body {
119	    width: 100%;
120	    min-height: 100vh;
121	    overflow-x: hidden;
122	    display: flex;
123	    flex-direction: column;
124	    font-family: var(--font-sans);
125	    font-size: var(--fs-body);
126	    line-height: 1.65;
127	    color: var(--text);
128	    background-color: var(--canvas);
129	    background-image: radial-gradient(120% 60% at 50% -10%,
130	                                      rgba(15, 42, 46, .07), transparent 60%);
131	    background-repeat: no-repeat;
132	    -webkit-font-smoothing: antialiased;
133	    -moz-osx-font-smoothing: grayscale;
134	}
135	
136	#app {
137	    display: flex;
138	    flex-direction: column;
139	    min-height: 100vh;
140	    width: 100%;
141	}
142	
143	img { display: block; max-width: 100%; }
144	
145	a { color: var(--accent); }
146	a:hover { color: var(--accent-hover); }
147	
148	/* ==========================================================================
149	   3. PAGE LAYOUT
150	   ========================================================================== */
151	.page-container {
152	    max-width: var(--wrap);
153	    width: 100%;
154	    margin: 0 auto;
155	    flex: 1;
156	    padding: calc(var(--header-h) + var(--s7)) var(--s5) var(--s8);
157	}
158	
159	.page-header {
160	    text-align: center;
161	    max-width: 720px;
162	    margin: 0 auto var(--s7);
163	}
164	
165	.page-title {
166	    font-family: var(--font-display);
167	    font-size: var(--fs-title);
168	    font-weight: 700;
169	    line-height: 1.15;
170	    letter-spacing: -.01em;
171	    color: var(--ink);
172	    margin-bottom: var(--s3);
173	}
174	
175	.page-subtitle {
176	    font-size: 1.05rem;
177	    color: var(--text-2);
178	}
179	
180	.section-title {
181	    font-family: var(--font-display);
182	    font-size: var(--fs-section);
183	    font-weight: 700;
184	    color: var(--ink);
185	    text-align: center;
186	    margin-bottom: var(--s6);
187	}
188	```
